import{_ as a,o as e,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Filtro por número no Relatório Geral","description":"","frontmatter":{"title":"Filtro por número no Relatório Geral","id":"eproc-filtro-numero-relatorio","plataforma":"eproc","grupo":"Relatórios","plano":"free","desde":"1.10.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-filtro-numero-relatorio.md","filePath":"funcionalidades/eproc-filtro-numero-relatorio.md"}'),t={name:"funcionalidades/eproc-filtro-numero-relatorio.md"};function i(n,o,l,c,d,m){return e(),r("div",null,o[0]||(o[0]=[s('<h1 id="filtro-por-numero-no-relatorio-geral" tabindex="-1">Filtro por número no Relatório Geral <a class="header-anchor" href="#filtro-por-numero-no-relatorio-geral" aria-label="Permalink to &quot;Filtro por número no Relatório Geral&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Mostra no Relatório Geral só os processos com certos dígitos no número, por exemplo os que começam com 5 e terminam em 0, 1 ou 2. É útil para quem divide o acervo pelos dígitos do número.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, Relatório Geral de Processos, na barra acima da tabela de resultados: o selo <strong>Filtrar nº</strong>, logo depois do título &quot;Processos&quot;. Com o filtro ativo, o selo fica azul e mostra o filtro e quantos processos da página aparecem, por exemplo &quot;5NNNNN[012] · 27 de 100&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Gere o Relatório Geral normalmente e clique em <strong>Filtrar nº</strong>.</li><li>O painel mostra o número do processo como uma fileira de caixas, agrupadas em Número, Verificador, Ano, J, TR e Origem. Clique na caixa da posição que quer filtrar, por exemplo o último dígito do número, antes do traço.</li><li>Abaixo, marque os dígitos aceitos nessa posição. Os botões <strong>Pares</strong> e <strong>Ímpares</strong> marcam esses grupos de uma vez, e <strong>Qualquer</strong> desmarca tudo. A caixa passa a mostrar o que aceita, como <strong>[0-2]</strong>. Onde nada estiver marcado, qualquer dígito serve.</li><li>O ano, a justiça (J), o tribunal (TR) e a origem (comarca, os 4 últimos dígitos do número) têm uma caixa cada. Clique nela e digite um ou mais valores separados por vírgula, com intervalos usando traço: por exemplo <strong>2022-2025, 2019</strong> para o ano ou <strong>0242, 0133</strong> para duas comarcas. Para o ano, há também atalhos com os últimos anos, que marcam e desmarcam cada um.</li><li>O rodapé mostra quantos processos da página passam no filtro. Clique em <strong>Aplicar</strong>.</li><li>Para ver tudo de novo, clique no &quot;x&quot; do selo, ou em <strong>Limpar</strong> dentro do painel e depois em <strong>Aplicar</strong>.</li></ol><p>Pelo teclado: com uma caixa selecionada, as teclas de 0 a 9 marcam os dígitos, as setas trocam de posição e Esc fecha o painel sem aplicar.</p><h3 id="combinar-criterios-diferentes" tabindex="-1">Combinar critérios diferentes <a class="header-anchor" href="#combinar-criterios-diferentes" aria-label="Permalink to &quot;Combinar critérios diferentes&quot;">​</a></h3><p>Quando a divisão depende do tipo de processo, use <strong>+ Outra regra</strong>. O processo aparece se casar com qualquer uma das regras. Exemplo (números fictícios):</p><ul><li>Regra 1: 1º dígito <strong>5</strong> e 7º dígito (o último do número) <strong>0, 1 e 2</strong> (como 5001231-10.2024…);</li><li>Regra 2: 1º dígito <strong>0</strong> e 6º dígito (o penúltimo) <strong>0, 1 e 2</strong> (como 0012315-10.2005…).</li></ul><h3 id="editar-a-mascara-manualmente" tabindex="-1">Editar a máscara manualmente <a class="header-anchor" href="#editar-a-mascara-manualmente" aria-label="Permalink to &quot;Editar a máscara manualmente&quot;">​</a></h3><p>Quem preferir pode marcar <strong>Editar a máscara manualmente</strong> e digitar o filtro direto: <strong>N</strong> aceita qualquer dígito e <strong>[012]</strong> aceita um dos dígitos entre colchetes, comparando com o começo do número. No ano, na justiça, no tribunal e na origem, uma lista entre chaves aceita qualquer um dos valores, como <code>NNNNNNN-NN.{2022-2025}.N.NN.{0242,0133}</code>. Regras vão separadas por vírgula. O exemplo acima fica <code>5NNNNN[012], 0NNNN[012]N</code>.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar. O filtro fica guardado e volta na próxima vez que você abrir o relatório.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O eproc carrega o relatório uma página por vez, e o filtro só alcança a página carregada. Se o relatório estiver mostrando poucos processos por página, o painel avisa e oferece o botão <strong>Mostrar 100 por página</strong>, para o filtro alcançar mais processos de uma vez.</li><li>O filtro é guardado separadamente para cada perfil/unidade do eproc.</li><li>Os processos ocultos pelo filtro nunca ficam marcados: se você usar o &quot;marcar todos&quot; do cabeçalho da tabela, só os processos visíveis continuam marcados. Assim, as ações em bloco do eproc e as do eploc (como &quot;Monitorar todos os processos desta página&quot;) só agem sobre o que aparece.</li></ul><figure class="demo"><div class="demo__tela"><iframe src="/manual/demos/filtro-numero/reel.html" title="Demonstração animada" loading="lazy" tabindex="-1"></iframe></div><figcaption>Demonstração animada</figcaption></figure>',18)]))}const g=a(t,[["render",i]]);export{u as __pageData,g as default};
